import { useState, useCallback } from 'react';
import Controls from './components/Controls';
import PhysicsCanvas from './components/PhysicsCanvas';
import { PhysicsSettings, BallItem } from './types';

const DEFAULT_SETTINGS: PhysicsSettings = {
  gravity: 0.35,
  restitution: 0.75,
  friction: 0.995,
};

const COLOR_PALETTE = [
  '#38bdf8',
  '#818cf8',
  '#c084fc',
  '#f472b6',
  '#34d399',
  '#fbbf24',
  '#f87171',
  '#a78bfa',
];

const generateUniqueId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const createInitialBalls = (): BallItem[] => {
  const balls: BallItem[] = [];
  const count = 8;
  for (let i = 0; i < count; i++) {
    const radius = 14 + Math.floor(Math.random() * 8);
    balls.push({
      id: generateUniqueId(),
      x: 80 + i * 45,
      y: 60 + Math.random() * 100,
      vx: (Math.random() - 0.5) * 6,
      vy: Math.random() * 3,
      radius,
      color: COLOR_PALETTE[i % COLOR_PALETTE.length],
      mass: radius,
    });
  }
  return balls;
};

const App = () => {
  const [settings, setSettings] = useState<PhysicsSettings>(DEFAULT_SETTINGS);
  const [balls, setBalls] = useState<BallItem[]>(createInitialBalls);

  const handleSettingsChange = useCallback(
    (key: keyof PhysicsSettings, value: number) => {
      setSettings((prev) => ({
        ...prev,
        [key]: value,
      }));
    },
    []
  );

  const handleAddBall = useCallback((ball: BallItem) => {
    setBalls((prev) => [...prev, ball]);
  }, []);

  const handleAddBalls = useCallback((count: number) => {
    const newBalls: BallItem[] = [];
    for (let i = 0; i < count; i++) {
      const radius = 12 + Math.floor(Math.random() * 12);
      newBalls.push({
        id: generateUniqueId(),
        x: 60 + Math.random() * 200,
        y: 50 + Math.random() * 120,
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 4,
        radius,
        color: COLOR_PALETTE[Math.floor(Math.random() * COLOR_PALETTE.length)],
        mass: radius,
      });
    }
    setBalls((prev) => [...prev, ...newBalls]);
  }, []);

  const handleClearBalls = useCallback(() => {
    setBalls([]);
  }, []);

  const handleResetDefaults = useCallback(() => {
    setSettings(DEFAULT_SETTINGS);
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">バウンドボール シミュレーター</h1>
        <p className="subtitle">
          重力・反発・摩擦を自在に操作できるインタラクティブ物理シミュレーション
        </p>
      </header>

      <main className="main-layout">
        <PhysicsCanvas
          settings={settings}
          balls={balls}
          onAddBall={handleAddBall}
        />
        <Controls
          settings={settings}
          onSettingsChange={handleSettingsChange}
          ballCount={balls.length}
          onAddBalls={handleAddBalls}
          onClearBalls={handleClearBalls}
          onResetDefaults={handleResetDefaults}
        />
      </main>
    </div>
  );
};

export default App;
